// questbuilder.test.js: the quest editor page, run against a fake DOM (#958
// builder fix review). Loads the real questmerge.js and quests.js, renders
// quest 11 and quest 76 as the page receives them, presses Save and reads the
// Build.Quest.Update payload the page sends.
//
// Run:  node tools/jstest/questbuilder.test.js
//
// Fixtures: tools/jstest/fixtures/quest-11.json and quest-76.json are the JSON
// of the shipped quest YAML (what Build.Quest sends the page). They are
// generated by modules/gmcp TestBuilderFixtures_MatchTheShippedQuests
// (UPDATE_QUEST_FIXTURES=1 go test ./modules/gmcp/ -run TestBuilderFixtures),
// which also fails when a shipped quest changes without its fixture.
//
// "Equal" below means equal once empty values are dropped from both sides
// (0, "", false, null, empty lists and objects): the Go side marshals with
// omitempty, so the page sending gold:0 for a quest with no gold changes
// nothing. A key that holds a value must match exactly.
//
// Dependency-free, like the other jstest files. Exits non-zero on failure.
'use strict';

var fs = require('fs');
var path = require('path');
var vm = require('vm');

var JS = path.join(__dirname, '..', '..', '_datafiles', 'html', 'public', 'static', 'js');
var FIX = path.join(__dirname, 'fixtures');

var failures = 0;
// firstDiff names the first path where two JSON values differ, for a short failure line.
function firstDiff(a, b, where) {
    if (JSON.stringify(a) === JSON.stringify(b)) return '';
    if (a && b && typeof a === 'object' && typeof b === 'object') {
        var keys = Object.keys(a).concat(Object.keys(b));
        for (var i = 0; i < keys.length; i++) {
            var d = firstDiff(a[keys[i]], b[keys[i]], where + '.' + keys[i]);
            if (d) return d;
        }
    }
    return where + ': got ' + JSON.stringify(a) + ', want ' + JSON.stringify(b);
}
function check(name, got, want) {
    var g = JSON.stringify(got), w = JSON.stringify(want);
    if (g !== w) {
        failures++;
        var d = firstDiff(got, want, '');
        console.log('FAIL ' + name + '\n  ' + (d.length < 600 ? d : d.slice(0, 600) + '...'));
        return;
    }
    console.log('ok   ' + name);
}

// --- a small fake DOM ---------------------------------------------------------

function Text(s) { this.nodeType = 3; this.textContent = s; this.parentNode = null; }

function El(tag) {
    this.nodeType = 1;
    this.tagName = tag.toUpperCase();
    this.attrs = {};
    this.children = [];
    this.parentNode = null;
    this.listeners = {};
    this.style = {};
    this.value = '';
    this.checked = false;
    this.textContent = '';
    var self = this;
    if (this.tagName === 'INPUT') {
        // A browser's text input drops line breaks from what it is given, so a
        // multi-line value in one cannot survive a save.
        var held = '';
        Object.defineProperty(this, 'value', {
            get: function () { return held; },
            set: function (v) { held = String(v).replace(/[\r\n]/g, ''); }
        });
    }
    if (this.tagName === 'SELECT') {
        Object.defineProperty(this, 'value', {
            get: function () {
                var opts = self.options;
                for (var i = 0; i < opts.length; i++) if (opts[i].selected) return opts[i].value;
                return opts.length ? opts[0].value : '';
            },
            set: function (v) {
                self.options.forEach(function (o) { o.selected = (o.value === v); });
            }
        });
        Object.defineProperty(this, 'options', {
            get: function () { return self.children.filter(function (c) { return c.tagName === 'OPTION'; }); }
        });
    }
}
El.prototype.setAttribute = function (k, v) {
    this.attrs[k] = v;
    if (k === 'value') this.value = v;
};
El.prototype.appendChild = function (c) {
    if (c.parentNode) c.parentNode.removeChild(c);
    c.parentNode = this; this.children.push(c); return c;
};
El.prototype.insertBefore = function (c, ref) {
    if (c.parentNode) c.parentNode.removeChild(c);
    c.parentNode = this;
    var i = ref ? this.children.indexOf(ref) : -1;
    if (i < 0) this.children.push(c); else this.children.splice(i, 0, c);
    return c;
};
El.prototype.removeChild = function (c) {
    var i = this.children.indexOf(c);
    if (i >= 0) this.children.splice(i, 1);
    c.parentNode = null; return c;
};
El.prototype.addEventListener = function (t, fn) { (this.listeners[t] = this.listeners[t] || []).push(fn); };
Object.defineProperty(El.prototype, 'innerHTML', {
    get: function () { return ''; },
    set: function (v) {
        if (v !== '') throw new Error('fake DOM: innerHTML only clears');
        this.children.forEach(function (c) { c.parentNode = null; });
        this.children = [];
    }
});
function sibling(el, d) {
    var p = el.parentNode; if (!p) return null;
    var i = p.children.indexOf(el) + d;
    return p.children[i] || null;
}
Object.defineProperty(El.prototype, 'previousElementSibling', { get: function () { return sibling(this, -1); } });
Object.defineProperty(El.prototype, 'nextElementSibling', { get: function () { return sibling(this, 1); } });

function fire(el, type, extra) {
    var ev = { target: el, key: '', stopPropagation: function () {}, preventDefault: function () {} };
    for (var k in extra || {}) ev[k] = extra[k];
    (el.listeners[type] || []).forEach(function (fn) { fn(ev); });
}

function walk(el, fn) { fn(el); (el.children || []).forEach(function (c) { if (c.nodeType === 1) walk(c, fn); }); }
function inRow(el) { for (var p = el.parentNode; p; p = p.parentNode) if (p._isRow) return true; return false; }

// --- loading the page ---------------------------------------------------------

function loadPage(questJson, enums) {
    var inspector = new El('div');
    inspector.attrs.id = 'inspector';
    var sent = [];
    var win = {
        Builder: { sendGMCP: function (pkg, obj) { sent.push({ pkg: pkg, obj: obj }); }, toast: function () {} },
        confirm: function () { return true; }
    };
    var doc = {
        createElement: function (tag) { return new El(tag); },
        createTextNode: function (s) { return new Text(s); },
        getElementById: function (id) {
            if (id === 'inspector') return inspector;
            var hit = null;
            walk(inspector, function (e) { if (!hit && e.attrs.id === id) hit = e; });
            return hit;
        }
    };
    var sandbox = { window: win, self: win, document: doc, console: console };
    vm.createContext(sandbox);
    ['questmerge.js', 'quests.js'].forEach(function (f) {
        vm.runInContext(fs.readFileSync(path.join(JS, f), 'utf8'), sandbox, { filename: f });
    });
    win.Builder.QuestsPanel.renderDetail({ found: true, quest: JSON.parse(JSON.stringify(questJson)), enums: enums });
    return {
        inspector: inspector, sent: sent,
        // labelled controls, in page order, outside any collapsed row unless inRows
        controls: function (label, inRows) {
            var out = [];
            walk(inspector, function (e) {
                if (e.tagName === 'LABEL' && e.textContent === label && e.parentNode.children[0] === e) {
                    if (!!inRow(e) === !!inRows) out.push(e.parentNode.children[1]);
                }
            });
            return out;
        },
        rowOf: function (el) { for (var p = el; p; p = p.parentNode) if (p._isRow) return p; return null; },
        save: function () {
            var btn = doc.getElementById('q-save');
            fire(btn, 'click');
            var last = sent[sent.length - 1];
            if (!last || last.pkg !== 'Build.Quest.Update') throw new Error('Save sent no Build.Quest.Update');
            return JSON.parse(JSON.stringify(last.obj));
        }
    };
}

// The event, action and token lists the server sends with Build.Quest.
var EVENTS = ['room_enter', 'room_gate', 'item_give', 'skill_use', 'mob_death', 'command', 'command_issued',
    'item_gain', 'quest_granted', 'look_at', 'search_at', 'spell_landed', 'topic_heard'];
var ACTIONS = ['grant', 'consume_item', 'give_item', 'give_gold', 'charge_gold', 'npc_say', 'actor', 'observer',
    'spawn_mob', 'spawn_item', 'teach_spell', 'train_skill', 'train_stat', 'learn_recipe', 'apply_condition',
    'teleport', 'give_mutation', 'set_flag', 'discover', 'sequence', 'bump_rep', 'declare_bounty'];
var ENUMS = {
    events: EVENTS.map(function (k) { return { key: k, description: '' }; }),
    actions: ACTIONS.map(function (k) { return { key: k, description: '' }; })
};

// prune drops empty values, as the Go side's omitempty does.
function prune(v) {
    if (Array.isArray(v)) {
        var a = v.map(prune);
        return a.length ? a : undefined;
    }
    if (v && typeof v === 'object') {
        var o = {};
        Object.keys(v).forEach(function (k) { var p = prune(v[k]); if (p !== undefined) o[k] = p; });
        return Object.keys(o).length ? o : undefined;
    }
    return (v === 0 || v === '' || v === false || v === null) ? undefined : v;
}
function load(n) { return JSON.parse(fs.readFileSync(path.join(FIX, 'quest-' + n + '.json'), 'utf8')); }
function clone(v) { return JSON.parse(JSON.stringify(v)); }

var q11 = load('11'), q76 = load('76');

// Fixture sanity: the interesting fields are really in the input, so an equal
// result is not two empty sides.
check('fixture 11 has branched steps', q11.steps.filter(function (s) { return s.branch; }).length > 0, true);
check('fixture 11 has step destinations', q11.steps.filter(function (s) { return s.destination && Object.keys(s.destination).length; }).length > 0, true);
check('fixture 76 has a trigger with missing_items',
    q76.triggers.filter(function (t) { return t.conditions && t.conditions.missing_items; }).length > 0, true);

// --- an unedited save -----------------------------------------------------------

[['11', q11], ['76', q76]].forEach(function (p) {
    var got = loadPage(p[1], ENUMS).save();
    check('quest ' + p[0] + ': an unedited save sends the quest it loaded', prune(got), prune(p[1]));
});

// --- one edit each --------------------------------------------------------------

// A cleared numeric field: quest 11's gold reward.
(function () {
    var pg = loadPage(q11, ENUMS);
    var gold = pg.controls('Gold')[0];
    gold.value = '';
    fire(gold, 'input');
    var want = clone(q11); delete want.rewards.gold;
    check('a cleared numeric field clears only itself', prune(pg.save()), prune(want));
})();

// An unchecked box: a copy of quest 11 made repeatable (neither quest is).
(function () {
    var src = clone(q11); src.repeatable = true;
    var pg = loadPage(src, ENUMS);
    var box = pg.controls('Repeatable')[0];
    check('the Repeatable box starts checked', box.checked, true);
    box.checked = false;
    fire(box, 'change');
    var want = clone(q11);
    check('an unchecked box clears only itself', prune(pg.save()), prune(want));
})();

// An emptied list: quest 76's trigger 9 has tokens in "Has ALL tokens".
(function () {
    var pg = loadPage(q76, ENUMS);
    var chips = pg.controls('Has ALL tokens', true)[9];
    var chip = chips.children.filter(function (c) { return c._val === '76-start'; })[0];
    fire(chip.children[1], 'click');
    var want = clone(q76); delete want.triggers[9].conditions.has;
    check('an emptied list clears only itself', prune(pg.save()), prune(want));
})();

// A changed trigger event: quest 76 trigger 10 (topic_heard: mob, topic) becomes skill_use.
(function () {
    var pg = loadPage(q76, ENUMS);
    var ev = pg.controls('Event', true)[10];
    ev.value = 'skill_use';
    fire(ev, 'change');
    var want = clone(q76);
    want.triggers[10].event = 'skill_use';
    delete want.triggers[10].mob; delete want.triggers[10].topic;
    check('a changed trigger event drops the old event\'s filters and keeps the rest', prune(pg.save()), prune(want));
})();

// Reordered rows: quest 11's second step moves above the first; each step keeps its own fields.
(function () {
    var pg = loadPage(q11, ENUMS);
    var row = pg.rowOf(pg.controls('Branch (the side this step belongs to)', true)[1]);
    var up = row.children[0].children.filter(function (c) { return c.textContent === '↑'; })[0];
    fire(up, 'click');
    var want = clone(q11);
    want.steps = [want.steps[1], want.steps[0]].concat(want.steps.slice(2));
    check('reordered steps keep their order and their own fields', prune(pg.save()), prune(want));
})();

// A cleared branch, and a refill of the picker afterwards (focus, mousedown).
(function () {
    var pg = loadPage(q11, ENUMS);
    var sel = pg.controls('Branch (the side this step belongs to)', true)[1];
    check('the picker starts on the loaded branch', sel.value, q11.steps[1].branch);
    sel.value = '';
    fire(sel, 'change');
    var want = clone(q11); delete want.steps[1].branch;
    check('a cleared branch is omitted', prune(pg.save()), prune(want));
    fire(sel, 'mousedown');
    fire(sel, 'focus');
    check('the picker stays on none after it refills', sel.value, '');
    check('a cleared branch stays cleared after the picker refills', prune(pg.save()), prune(want));
    sel.value = 'rhett';
    fire(sel, 'change');
    want.steps[1].branch = 'rhett';
    check('a changed branch lands', prune(pg.save()), prune(want));
})();

console.log(failures ? failures + ' FAILED' : 'all checks passed');
process.exit(failures ? 1 : 0);
